program='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # A horizontal 5-bar marks the width over which the vertical color strip
    # at its first column is copied.
    for r in range(h):
        c = 0
        while c < w:
            if grid[r][c] != 5:
                c += 1
                continue
            a = c
            while c < w and grid[r][c] == 5:
                c += 1
            b = c - 1
            if b == a:
                continue
            for dr in (-1, 1):
                rr = r + dr
                if not (0 <= rr < h) or grid[rr][a] in (0, 5):
                    continue
                rows = []
                while 0 <= rr < h and grid[rr][a] not in (0, 5):
                    rows.append(rr)
                    rr += dr
                for sr in rows:
                    color = grid[sr][a]
                    for cc in range(a, b + 1):
                        if out[sr][cc] != 5:
                            out[sr][cc] = color
                break

    # A vertical 5-bar marks the height over which an adjacent horizontal
    # color block is repeated. Its template is anchored at the bar's end.
    for c in range(w):
        r = 0
        while r < h:
            if grid[r][c] != 5:
                r += 1
                continue
            a = r
            while r < h and grid[r][c] == 5:
                r += 1
            b = r - 1
            if b == a:
                continue
            done = False
            for end in (b, a):
                for dc in (-1, 1):
                    cc = c + dc
                    if not (0 <= cc < w) or grid[end][cc] in (0, 5):
                        continue
                    # Find the contiguous colored run immediately beside the bar.
                    cols = []
                    x = cc
                    while 0 <= x < w and grid[end][x] not in (0, 5):
                        cols.append(x)
                        x += dc
                    # Gather adjacent rows with the same side run; this is the tile.
                    template_rows = [end]
                    step = -1 if end == b else 1
                    rr = end + step
                    while 0 <= rr < h and all(grid[rr][x] not in (0, 5) for x in cols):
                        template_rows.append(rr)
                        rr += step
                    template = [[grid[tr][x] for x in cols] for tr in template_rows]
                    # Repeat the tile along the 5-bar, aligned to its endpoint.
                    for tr in range(a, b + 1):
                        offset = abs(tr - end) % len(template)
                        vals = template[offset]
                        for j, x in enumerate(cols):
                            if out[tr][x] != 5:
                                out[tr][x] = vals[j]
                    done = True
                    break
                if done:
                    break
    return out
'''
